-- Vendor checks and ratings, quotations, invoice matching, school store billing.
ALTER TABLE public.inv_suppliers ADD COLUMN pan VARCHAR(10) NOT NULL DEFAULT '', ADD COLUMN bank_account VARCHAR(20) NOT NULL DEFAULT '', ADD COLUMN ifsc VARCHAR(11) NOT NULL DEFAULT '', ADD COLUMN msme VARCHAR(30) NOT NULL DEFAULT '',
  ADD COLUMN bank_status VARCHAR(10) NOT NULL DEFAULT 'Pending' CHECK (bank_status IN ('Pending', 'Verified')),
  ADD COLUMN vendor_status VARCHAR(14) NOT NULL DEFAULT 'Pending checks' CHECK (vendor_status IN ('Pending checks', 'Verified', 'Rejected', 'Blacklisted')),
  ADD COLUMN rating NUMERIC(2,1) CHECK (rating BETWEEN 1 AND 5);
CREATE SEQUENCE public.inv_rfq_seq START 62; CREATE SEQUENCE public.store_bill_seq START 419;
CREATE TABLE public.inv_rfqs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('RFQ-' || lpad(nextval('public.inv_rfq_seq')::text, 3, '0')), item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), closes_on DATE NOT NULL, status VARCHAR(8) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Awarded')), award_reason VARCHAR(200), po_id UUID REFERENCES public.inv_pos(id) ON DELETE SET NULL);
CREATE TABLE public.inv_quotes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), rfq_id UUID NOT NULL REFERENCES public.inv_rfqs(id) ON DELETE CASCADE, supplier_id UUID NOT NULL REFERENCES public.inv_suppliers(id) ON DELETE CASCADE, unit_price INTEGER NOT NULL CHECK (unit_price > 0), delivery_days INTEGER NOT NULL CHECK (delivery_days >= 0), warranty VARCHAR(30) NOT NULL DEFAULT '', terms VARCHAR(40) NOT NULL DEFAULT '', UNIQUE (rfq_id, supplier_id));
CREATE TABLE public.inv_bills (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, po_id UUID NOT NULL REFERENCES public.inv_pos(id) ON DELETE CASCADE, bill_no VARCHAR(30) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), billed_on DATE NOT NULL DEFAULT CURRENT_DATE, decision VARCHAR(20) NOT NULL DEFAULT 'Open' CHECK (decision IN ('Open', 'Sent for payment', 'Held')), pay_amount INTEGER, UNIQUE (institution_id, bill_no));
CREATE TABLE public.store_bills (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('SB-' || lpad(nextval('public.store_bill_seq')::text, 4, '0')), student_id UUID REFERENCES public.students(id) ON DELETE SET NULL, amount INTEGER NOT NULL DEFAULT 0, paid_by VARCHAR(10) NOT NULL CHECK (paid_by IN ('Cash', 'UPI', 'Card', 'Online')), sold_at VARCHAR(12) NOT NULL DEFAULT 'Counter' CHECK (sold_at IN ('Counter', 'Parent app')), sold_on DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE public.store_bill_lines (bill_id UUID NOT NULL REFERENCES public.store_bills(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), price INTEGER NOT NULL CHECK (price >= 0), PRIMARY KEY (bill_id, item_id));
ALTER TABLE public.inv_rfqs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_quotes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_bills ENABLE ROW LEVEL SECURITY; ALTER TABLE public.store_bills ENABLE ROW LEVEL SECURITY; ALTER TABLE public.store_bill_lines ENABLE ROW LEVEL SECURITY;
